diff --git a/client/lib/paths/login/index.js b/client/lib/paths/login/index.js
index f3848cf1be835..f256421a26c7b 100644
--- a/client/lib/paths/login/index.js
+++ b/client/lib/paths/login/index.js
@@ -16,6 +16,7 @@ export function login( {
 	socialConnect,
 	emailAddress,
 	socialService,
+	oauth2ClientId,
 } = {} ) {
 	let url = config( 'login_url' );

@@ -51,5 +52,9 @@ export function login( {
 		url = addQueryArgs( { email_address: emailAddress }, url );
 	}

+	if ( oauth2ClientId && ! isNaN( oauth2ClientId ) ) {
+		url = addQueryArgs( { client_id: oauth2ClientId }, url );
+	}
+
 	return url;
 }

